css:
.bt-footer{--navy:#004877;--ink:#252627;--cream:#F9F4EC;--sand:#F3E9D9;--sky:#3C96E7;--pale:#AED3F5;--line:rgba(174,211,245,.2);--soft:rgba(255,255,255,.74);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);position:relative;overflow:hidden;background:linear-gradient(180deg,#004877 0%,#00365b 42%,#001d33 100%);color:#fff;font-family:var(--sans);font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased;text-align:left}
.bt-footer *,.bt-footer *::before,.bt-footer *::after{box-sizing:border-box}
.bt-footer{font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-footer a{color:inherit;text-decoration:none}
.bt-footer ul{list-style:none;margin:0;padding:0}
.bt-footer p,.bt-footer dl,.bt-footer dd,.bt-footer dt{margin:0}
.bt-footer img{display:block;max-width:100%}
.bt-footer svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.bt-footer a:focus-visible,.bt-footer button:focus-visible,.bt-footer input:focus-visible{outline:2px solid var(--pale);outline-offset:3px}
.bt-footer .bt-f-wrap{position:relative;z-index:2;max-width:1432px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}

.bt-footer .bt-f-main{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.95fr) minmax(0,1.05fr);gap:clamp(28px,5vw,88px);padding-top:clamp(48px,5vw,72px)}
.bt-footer .bt-f-logo{display:inline-block}
.bt-footer .bt-f-logo img{width:min(270px,100%);height:auto}
.bt-footer .bt-f-line{font-family:var(--serif);font-size:clamp(21px,1.9vw,26px);line-height:1.2;margin-top:22px;max-width:20ch}
.bt-footer .bt-f-line em{font-style:italic;color:var(--pale)}
.bt-footer .bt-news{display:flex;align-items:center;min-width:0;max-width:400px;margin-top:26px;border:1px solid var(--line);background:rgba(255,255,255,.06);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);transition:border-color .4s var(--ease),background .4s var(--ease)}
.bt-footer .bt-news:focus-within{border-color:var(--pale);background:rgba(255,255,255,.1)}
.bt-footer .bt-news input{flex:1;min-width:0;width:100%;height:50px;border:0;background:transparent;color:#fff;font-family:var(--sans);font-size:15px;padding:0 0 0 16px;outline:0;border-radius:0}
.bt-footer .bt-news input::placeholder{color:rgba(255,255,255,.62)}
.bt-footer .bt-news button{display:inline-flex;align-items:center;gap:9px;height:50px;border:0;border-left:1px solid var(--line);background:transparent;color:#fff;font-family:var(--sans);font-size:11.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;padding:0 16px;transition:background .4s var(--ease),color .4s var(--ease)}
.bt-footer .bt-news button:hover{background:var(--cream);color:var(--navy)}
.bt-footer .bt-news button svg{width:14px;height:14px;transition:transform .5s var(--ease)}
.bt-footer .bt-news button:hover svg{transform:translateX(4px)}
.bt-footer .bt-news-p{font-size:13px;color:var(--soft);margin-top:10px}

.bt-footer .bt-f-h{font-size:11px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:var(--pale);margin-bottom:14px}
.bt-footer .bt-f-nap{font-family:var(--serif);font-size:19px;line-height:1.35;font-style:normal}
.bt-footer .bt-f-tel{display:inline-block;font-family:var(--serif);font-size:27px;line-height:1.1;margin:10px 0 16px;background:linear-gradient(currentColor,currentColor) 0 100%/100% 1px no-repeat;padding-bottom:5px;transition:color .4s var(--ease)}
.bt-footer .bt-f-tel:hover{color:var(--pale)}
.bt-footer .bt-f-hours{font-size:14.5px;color:var(--soft);max-width:300px}
.bt-footer .bt-f-hours div{display:flex;justify-content:space-between;gap:16px;padding:5px 0}
.bt-footer .bt-f-hours div+div{border-top:1px solid var(--line)}
.bt-footer .bt-f-hours dd{color:#fff;white-space:nowrap}
.bt-footer .bt-f-dir{display:inline-flex;align-items:center;gap:10px;margin-top:16px;font-size:11.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;border-bottom:1px solid currentColor;padding-bottom:5px;transition:gap .5s var(--ease),color .4s var(--ease)}
.bt-footer .bt-f-dir:hover{gap:16px;color:var(--pale)}
.bt-footer .bt-f-dir svg{width:14px;height:14px}

.bt-footer .bt-f-nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(20px,3vw,48px)}
.bt-footer .bt-f-nav li{margin-bottom:7px}
.bt-footer .bt-f-nav li a{position:relative;display:inline-block;font-size:15px;color:var(--soft);transition:color .35s var(--ease),transform .5s var(--ease)}
.bt-footer .bt-f-nav li a::before{content:"";position:absolute;left:-16px;top:50%;width:6px;height:6px;margin-top:-3px;border:1px solid var(--pale);transform:rotate(45deg) scale(0);opacity:0;transition:transform .5s var(--ease),opacity .4s var(--ease)}
.bt-footer .bt-f-nav li a:hover{color:#fff;transform:translateX(16px)}
.bt-footer .bt-f-nav li a:hover::before{transform:rotate(45deg) scale(1);opacity:1}

/* 3D tiled floor with the name standing on the horizon */
.bt-footer .bt-f-base{position:relative;margin-top:clamp(30px,3.4vw,52px)}
.bt-footer .bt-f-word{display:block;position:relative;z-index:1;text-align:center;white-space:nowrap;font-family:var(--serif);font-weight:400;font-size:min(11.4vw,188px);line-height:.86;letter-spacing:-.012em;color:transparent;background:linear-gradient(180deg,rgba(174,211,245,.62) 0%,rgba(174,211,245,.3) 52%,rgba(174,211,245,.04) 92%);-webkit-background-clip:text;background-clip:text;user-select:none;pointer-events:none}
.bt-footer .bt-f-floorbox{position:absolute;left:0;right:0;top:min(7vw,116px);bottom:0;overflow:hidden;perspective:420px;perspective-origin:50% 0;pointer-events:none;-webkit-mask-image:linear-gradient(180deg,transparent 0,rgba(0,0,0,.55) 16%,#000 46%,#000 62%,rgba(0,0,0,.32) 100%);mask-image:linear-gradient(180deg,transparent 0,rgba(0,0,0,.55) 16%,#000 46%,#000 62%,rgba(0,0,0,.32) 100%)}
.bt-footer .bt-f-floor{position:absolute;left:-150%;right:-150%;top:0;height:1400px;transform-origin:50% 0;transform:translateZ(-380px) rotateX(76deg);background-image:linear-gradient(rgba(174,211,245,.5) 2px,transparent 2px),linear-gradient(90deg,rgba(174,211,245,.5) 2px,transparent 2px),repeating-conic-gradient(rgba(174,211,245,.1) 0 25%,rgba(174,211,245,0) 0 50%);background-size:96px 96px,96px 96px,192px 192px;background-position:50% 0,50% 0,50% 0;animation:btFloor 22s linear infinite}
.bt-footer .bt-f-glow{position:absolute;left:50%;top:min(6.4vw,106px);z-index:0;width:min(1100px,96%);height:240px;margin-left:calc(min(1100px,96%) / -2);transform:translateY(-50%);background:radial-gradient(ellipse at center,rgba(174,211,245,.26) 0%,rgba(174,211,245,.08) 38%,rgba(174,211,245,0) 68%);pointer-events:none}
@keyframes btFloor{to{background-position:50% 192px,50% 192px,50% 192px}}

.bt-footer .bt-f-bot{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px 28px;margin-top:clamp(18px,2.6vw,40px);padding-top:18px;padding-bottom:22px;font-size:13px;color:rgba(255,255,255,.82)}
.bt-footer .bt-f-legal{display:flex;flex-wrap:wrap;gap:6px 22px}
.bt-footer .bt-f-legal a{transition:color .3s var(--ease)}
.bt-footer .bt-f-legal a:hover{color:var(--pale)}
.bt-footer .bt-built{display:inline-flex;align-items:center;gap:8px;font-size:13px}
.bt-footer .bt-built b{color:var(--pale)}
.bt-footer .bt-built-ico{width:22px;height:22px;border-radius:6px;flex-shrink:0}

@media (max-width:1023px){
.bt-footer .bt-f-main{grid-template-columns:repeat(2,minmax(0,1fr))}
.bt-footer .bt-f-brand{grid-column:1 / -1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 clamp(28px,5vw,88px);align-items:end}
.bt-footer .bt-f-brand .bt-f-logo,.bt-footer .bt-f-brand .bt-f-line{grid-column:1}
.bt-footer .bt-f-brand .bt-news{grid-column:2;grid-row:1 / 3;align-self:end;margin-top:0}
.bt-footer .bt-f-brand .bt-news-p{grid-column:2}
}
@media (max-width:760px){
.bt-footer{padding-bottom:calc(66px + env(safe-area-inset-bottom))}
.bt-footer .bt-f-main{grid-template-columns:minmax(0,1fr);gap:30px}
.bt-footer .bt-f-brand{display:block}
.bt-footer .bt-f-brand .bt-news{margin-top:22px;max-width:none}
.bt-footer .bt-f-line{max-width:none}
.bt-footer .bt-f-hours{max-width:none}
.bt-footer .bt-f-tel{font-size:25px}
.bt-footer .bt-f-nav li a:hover{transform:none}
.bt-footer .bt-f-nav li a::before{display:none}
.bt-footer .bt-f-floor{background-size:64px 64px,64px 64px,128px 128px;animation-name:btFloorS}
.bt-footer .bt-f-bot{flex-direction:column;align-items:flex-start;gap:8px}
}
@keyframes btFloorS{to{background-position:50% 128px,50% 128px,50% 128px}}
@media (prefers-reduced-motion:reduce){.bt-footer *{transition-duration:.01ms!important}.bt-footer .bt-f-floor{animation:none}}
